import styled from '@emotion/styled';

interface StickyScrollRootStylesProps {
  $showBackground?: boolean;
  $isExportPage?: boolean;
  $isResponsivePage?: boolean;
  $isTabPage?: boolean;
  $hiddenAll?: boolean;
  $showContent?: boolean;
}

export const StickyScrollRootStyles = styled.div<StickyScrollRootStylesProps>(
  ({
    $showBackground,
    $isExportPage,
    $isResponsivePage,
    $isTabPage,
    $hiddenAll,
    $showContent,
  }) => ({
    display: 'flex',
    flexDirection: 'column',
    gap: '24px',
    position: 'sticky',
    top: '56px',
    padding: '24px 0 24px max(96px, 50% - 664px)',
    zIndex: 110,
    background: 'transparent',

    '&::before': {
      content: '""',
      position: 'absolute',
      inset: 0,
      background: `linear-gradient(0deg, rgba(92, 72, 27, 0.04), rgba(92, 72, 27, 0.04)),
    linear-gradient(180deg, rgba(170, 106, 0, 0) 0%, rgba(195, 153, 85, 0.1) 100%),
    #FFFFFF`,
      backgroundAttachment: 'fixed',
      opacity: $showBackground ? 1 : 0,
      transition: 'opacity 0.1s ease',
      zIndex: -1,
    },
    ...($isExportPage && {
      paddingLeft: 'max(96px, 50% - 834px)',
    }),
    ...($isResponsivePage && {
      paddingLeft: 'max(80px, calc(40px + 50% - 548px))',

      '@media (min-width: 1440px)': {
        paddingLeft: 'max(80px, calc(40px + 50% - 628px))',
      },
      '@media (min-width: 1920px)': {
        paddingLeft: 'max(80px, calc(40px + 50% - 720px))',
      },
    }),
    ...($isTabPage && {
      paddingLeft: 'calc(max(96px, 50% - 664px) + 8px)',
    }),
    ...($hiddenAll && {
      paddingTop: 0,
      paddingBottom: 0,
    }),
    ...($showContent === false && { gap: 0 }),
    ...($isTabPage &&
      $isResponsivePage && {
        paddingLeft: 'calc(max(80px, calc(40px + 50% - 548px)) + 8px)',

        '@media (min-width: 1440px)': {
          paddingLeft: 'calc(max(80px, calc(40px + 50% - 628px)) + 8px)',
        },

        '@media (min-width: 1920px)': {
          paddingLeft: 'calc(max(80px, calc(40px + 50% - 720px)) + 8px)',
        },
      }),
  }),
);
